#include "stdlib/blas/ext/base/ndarray/svander.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create a data buffer for the input vector:
	float dataX[] = { 1.0f, 2.0f, 3.0f };

	// Specify the number of array dimensions:
	const int64_t ndimsX = 1;

	// Specify the array shape:
	int64_t shapeX[] = { 3 };

	// Specify the array strides:
	int64_t stridesX[] = { STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT };

	// Specify the byte offset:
	const int64_t offset = 0;

	// Specify the array order:
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;

	// Specify the index mode:
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;

	// Specify the subscript index modes:
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR, STDLIB_NDARRAY_INDEX_ERROR };
	const int64_t nsubmodes = 2;

	// Create an input ndarray:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataX, ndimsX, shapeX, stridesX, offset, order, imode, 1, submodes );

	// Create a data buffer for the output matrix:
	float dataOut[ 9 ] = { 0.0f };

	// Specify the number of array dimensions for the output:
	const int64_t ndimsOut = 2;

	// Specify the output array shape:
	int64_t shapeOut[] = { 3, 3 };

	// Specify the array strides:
	int64_t stridesOut[] = { 3 * STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT, STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT };

	// Create an output ndarray:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *out = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataOut, ndimsOut, shapeOut, stridesOut, offset, order, imode, nsubmodes, submodes );

	// Create a data buffer for an ndarray containing the mode:
	const float mdata[] = { 1.0f };

	// Specify the array strides for a zero-dimensional ndarray:
	int64_t mstrides[] = { 0 };

	// Create an ndarray containing the mode:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *mode = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)mdata, 0, NULL, mstrides, 0, order, imode, 1, submodes );

	if ( x == NULL || out == NULL || mode == NULL ) {
		fprintf( stderr, "Error allocating memory.\n" );
		exit( 1 );
	}

	// Define a list of ndarrays:
	const struct ndarray *arrays[] = { x, out, mode };

	// Perform computation:
	stdlib_blas_ext_svander( arrays );

	// Print the result:
	for ( int i = 0; i < 3; i++ ) {
		for ( int j = 0; j < 3; j++ ) {
			printf( "out[ %i, %i ] = %f\n", i, j, dataOut[ ( i * 3 ) + j ] );
		}
	}

	// Free allocated memory:
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( out );
	stdlib_ndarray_free( mode );
}
